using NUnit.Framework;
using UnityEditor;
using UnityEngine;

namespace Aedes.Module3.Sim.Tests
{
    /// <summary>
    /// The outdoor life (M3OutdoorLife) loads its animals, walker bodies and swaying-leaf materials
    /// from Resources/Module3/M3OutdoorLifeSet, generated by Module3OutdoorLifeAssets. If the set
    /// is missing or half-filled nothing fails in play mode: the village just stands still, and a
    /// leaf material that lost its texture draws its fronds as solid quads. This is what would
    /// notice. The set's own type lives in Assembly-CSharp, which this assembly cannot see, so it
    /// is read through SerializedObject.
    /// </summary>
    [TestFixture]
    public class OutdoorLifeAssetTests
    {
        private const string SetPath = "Assets/Resources/Module3/M3OutdoorLifeSet.asset";
        private const string FoliageShader = "AEDES/Module 3/Foliage Lit";

        // The shared tree prefabs the leaf swaps are read from (Module3OutdoorLifeAssets).
        private static readonly string[] TreePrefabs =
        {
            "Assets/1.TeamWorkspace/Team Assets/Prefabs/Neture/PF_CoconutTree.prefab",
            "Assets/1.TeamWorkspace/Team Assets/Prefabs/Neture/PF_BananaTree.prefab",
        };

        [Test]
        public void TheFoliageShaderExists()
        {
            var shader = Shader.Find(FoliageShader);
            Assert.IsNotNull(shader, $"no '{FoliageShader}' shader: the trees cannot sway");
            // Shader.Find still returns a shader that failed to compile (Unity substitutes its pink error
            // shader when it is drawn), so ask whether it has errors, and whether it runs on this platform.
            Assert.IsFalse(ShaderUtil.ShaderHasError(shader), $"'{FoliageShader}' has compile errors (see the console)");
            Assert.IsTrue(shader.isSupported, $"'{FoliageShader}' is not supported here: no subshader runs");
        }

        [Test]
        public void EveryLeafSwapReplacesAMaterialTheTreesReallyUse()
        {
            // ApplyWind swaps a material only where it finds the 'from' one, and silently swaps nothing when it
            // does not: a tree prefab that changed its leaf material would stop swaying and every other test
            // here would still pass.
            var set = AssetDatabase.LoadAssetAtPath<ScriptableObject>(SetPath);
            Assert.IsNotNull(set, $"{SetPath} is missing");
            var swaps = new SerializedObject(set).FindProperty("foliage");

            var used = new System.Collections.Generic.HashSet<Material>();
            foreach (string path in TreePrefabs)
            {
                var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
                Assert.IsNotNull(prefab, $"no tree prefab at {path}");
                foreach (var r in prefab.GetComponentsInChildren<Renderer>(true))
                    foreach (var m in r.sharedMaterials)
                        if (m != null) used.Add(m);
            }

            for (int i = 0; i < swaps.arraySize; i++)
            {
                var from = swaps.GetArrayElementAtIndex(i).FindPropertyRelative("from").objectReferenceValue as Material;
                Assert.IsNotNull(from, $"swap {i} has no source material");
                Assert.IsTrue(used.Contains(from), $"swap {i} replaces '{from.name}', which neither tree prefab uses any more");
            }
        }

        [Test]
        public void EachLeafMaterialCarriesItsWindRangeAndAlphaMode()
        {
            // The wind runs from where a plant's leaves begin to where they end, read from two material floats
            // (see M3FoliageSway.hlsl); 0 and 0 makes the shader fall back to a fixed reach that is right for
            // neither plant. And a leaf with a cut-out must keep its alpha clip: only a leaf whose source
            // material has none may turn it off (_M3_OPAQUE), or its fronds would draw as solid quads.
            var set = AssetDatabase.LoadAssetAtPath<ScriptableObject>(SetPath);
            Assert.IsNotNull(set, $"{SetPath} is missing");
            var swaps = new SerializedObject(set).FindProperty("foliage");
            for (int i = 0; i < swaps.arraySize; i++)
            {
                var swap = swaps.GetArrayElementAtIndex(i);
                var from = swap.FindPropertyRelative("from").objectReferenceValue as Material;
                var to = swap.FindPropertyRelative("to").objectReferenceValue as Material;
                Assert.IsNotNull(from);
                Assert.IsNotNull(to);

                float near = to.GetFloat("_ClearCoatMask"), far = to.GetFloat("_ClearCoatSmoothness");
                Assert.Greater(far, near + 0.05f, $"{to.name} has no measured wind range (AEDES > Module 3 > Generate Outdoor Life Assets)");

                bool cutOut = from.HasProperty("_AlphaClip") ? from.GetFloat("_AlphaClip") > 0.5f : from.IsKeywordEnabled("_ALPHATEST_ON");
                Assert.AreEqual(!cutOut, to.IsKeywordEnabled("_M3_OPAQUE"),
                    $"{to.name}: the source leaf {(cutOut ? "has a cut-out, so it must keep the alpha clip" : "has no cut-out, so it should skip the alpha clip")}");
            }
        }

        [Test]
        public void EveryAnimalAndWalkerBodyDrawsWithARealMaterial()
        {
            // A prefab whose material asset went missing does not fail anywhere: it draws magenta
            // (PF_DragonFlyYellow does). The generator leaves that one out; this is what would notice another.
            var set = AssetDatabase.LoadAssetAtPath<ScriptableObject>(SetPath);
            Assert.IsNotNull(set, $"{SetPath} is missing");
            var so = new SerializedObject(set);

            var bad = new System.Collections.Generic.SortedSet<string>();
            foreach (string array in new[] { "dragonflies", "walkers" })
            {
                var prop = so.FindProperty(array);
                for (int i = 0; i < prop.arraySize; i++)
                    CheckDrawable(prop.GetArrayElementAtIndex(i).objectReferenceValue as GameObject, bad);
            }
            CheckDrawable(so.FindProperty("frog").objectReferenceValue as GameObject, bad);
            Assert.IsEmpty(bad, "these would draw magenta:\n  " + string.Join("\n  ", bad));
        }

        private static void CheckDrawable(GameObject prefab, System.Collections.Generic.ICollection<string> bad)
        {
            if (prefab == null) return;
            foreach (var r in prefab.GetComponentsInChildren<Renderer>(true))
            {
                var materials = r.sharedMaterials;
                if (materials.Length == 0) bad.Add($"{prefab.name}/{r.name}: no materials");
                foreach (var m in materials)
                {
                    if (m == null) bad.Add($"{prefab.name}/{r.name}: a missing material");
                    else if (m.shader == null || m.shader.name == "Hidden/InternalErrorShader")
                        bad.Add($"{prefab.name}/{r.name}: '{m.name}' has no working shader");
                }
            }
        }

        [Test]
        public void TheSetNamesEveryPrefabItNeeds()
        {
            var set = AssetDatabase.LoadAssetAtPath<ScriptableObject>(SetPath);
            Assert.IsNotNull(set, $"{SetPath} is missing (AEDES > Module 3 > Generate Outdoor Life Assets)");
            var so = new SerializedObject(set);

            Assert.GreaterOrEqual(Count(so, "dragonflies"), 1, "no dragonfly prefab in the set");
            Assert.IsNotNull(so.FindProperty("frog").objectReferenceValue, "no frog prefab in the set");
            Assert.GreaterOrEqual(Count(so, "walkers"), 1, "no walker body in the set");
        }

        [Test]
        public void TheLeafMaterialsSwayAndKeepTheirTextures()
        {
            var set = AssetDatabase.LoadAssetAtPath<ScriptableObject>(SetPath);
            Assert.IsNotNull(set, $"{SetPath} is missing");
            var swaps = new SerializedObject(set).FindProperty("foliage");
            Assert.IsNotNull(swaps);
            Assert.GreaterOrEqual(swaps.arraySize, 2, "expected a palm and a banana leaf material");

            for (int i = 0; i < swaps.arraySize; i++)
            {
                var swap = swaps.GetArrayElementAtIndex(i);
                var from = swap.FindPropertyRelative("from").objectReferenceValue as Material;
                var to = swap.FindPropertyRelative("to").objectReferenceValue as Material;
                Assert.IsNotNull(from, $"swap {i} has no source material");
                Assert.IsNotNull(to, $"swap {i} has no swaying material");
                Assert.AreEqual(FoliageShader, to.shader.name, $"{to.name} is not on the foliage shader");
                // Alpha clipping is hard-coded in the fork, so a leaf copy that lost its texture would clip nothing
                // and draw every frond as a solid quad; the copy must carry what the original carries.
                if (from.HasProperty("_BaseMap") && from.GetTexture("_BaseMap") != null)
                    Assert.AreEqual(from.GetTexture("_BaseMap"), to.GetTexture("_BaseMap"), $"{to.name} lost {from.name}'s base map");
            }
        }

        private static int Count(SerializedObject so, string array)
        {
            var prop = so.FindProperty(array);
            if (prop == null || !prop.isArray) return 0;
            int n = 0;
            for (int i = 0; i < prop.arraySize; i++)
                if (prop.GetArrayElementAtIndex(i).objectReferenceValue != null) n++;
            return n;
        }
    }
}
